def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    return float(math.log1p(v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r * r * r
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    sites = s.get('sites', [])
    occ = [max(0.0, t.get('occupancy', 1.0)) if t.get('occupancy', 1.0) is not None else 0.0 for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    nearest = [math.inf for t in sites]
    bonds = s.get('neighbors', [])
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[b['j']] > 0:
            nearest[b['i']] = min(nearest[b['i']], d)
    counts = [0.0 for t in sites]
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0 and d <= 1.25 * nearest[b['i']]:
            counts[b['i']] += occ[b['j']]
    return float(sum(occ[i] * counts[i] for i in range(len(sites))) / weight)

def feature(s):
    sites = s.get('sites', [])
    occ = [max(0.0, t.get('occupancy', 1.0)) if t.get('occupancy', 1.0) is not None else 0.0 for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    nearest = [math.inf for t in sites]
    bonds = s.get('neighbors', [])
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[b['j']] > 0:
            nearest[b['i']] = min(nearest[b['i']], d)
    counts = [0.0 for t in sites]
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0 and d <= 1.25 * nearest[b['i']]:
            counts[b['i']] += occ[b['j']]
    mean = sum(occ[i] * counts[i] for i in range(len(sites))) / weight
    if mean <= 0:
        return 0.0
    var = sum(occ[i] * (counts[i] - mean) ** 2 for i in range(len(sites))) / weight
    return float(math.sqrt(max(0.0, var)) / mean)

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z):
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    props = s.get('element_properties', {})
    entries = []
    for e, x in s.get('composition', {}).items():
        p = props.get(e, {})
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if x is not None and x > 0 and ion is not None and affinity is not None and math.isfinite(ion) and math.isfinite(affinity):
            hardness = ion - affinity
            if hardness > 1e-8:
                entries += [(x, 0.5 * (ion + affinity), hardness)]
    weight = sum(t[0] for t in entries)
    inverse = sum(t[0] / t[2] for t in entries)
    if weight <= 0 or inverse <= 0:
        return 0.0
    chemical_potential = sum(t[0] * t[1] / t[2] for t in entries) / inverse
    variance = sum(t[0] * ((chemical_potential - t[1]) / t[2]) ** 2 for t in entries) / weight
    return float(math.sqrt(max(0.0, variance)))
